	InputPath       string
	OutputDir       string
	OutputTemplate  string
	ProviderName    string
	RendererName    string
	Model           string
	SourceLanguage  string
	TargetLanguage  string
	Timeout         time.Duration
	SaveLayoutJSON  bool
	RenderOptions   base.RenderOptions
