	if cfg.DefaultFontSize <= 0 {
		return fmt.Errorf("font size must be positive")
	}
	if cfg.OverlayOpacity < 0 || cfg.OverlayOpacity > 1 {
		return fmt.Errorf("overlay opacity must be between 0 and 1")
