	if r.SourceImageWidth <= 0 || r.SourceImageHeight <= 0 {
		return fmt.Errorf("source image dimensions must be positive")
	}
	if r.SourceLanguage == "" {
		return fmt.Errorf("source language is required")
	}
	if r.TargetLanguage == "" {
		return fmt.Errorf("target language is required")
	}
	return nil
}

