		req.Now = time.Now
	}
	if req.Timeout <= 0 {
		req.Timeout = 30 * time.Second
	}
	if req.OutputDir == "" {
		req.OutputDir = filepath.Dir(req.InputPath)
	}

	providerFactory, ok := a.ProviderFactories[req.ProviderName]
	if !ok {
		return RenderResult{}, fmt.Errorf("unknown provider %q", req.ProviderName)
	}
