		return err
	}
	defer file.Close()
	return png.Encode(file, img)
}

func makeAppIcon() image.Image {
	img := image.NewRGBA(image.Rect(0, 0, 512, 512))
	draw.Draw(img, img.Bounds(), &image.Uniform{color.RGBA{0xF4, 0xE8, 0xD2, 0xFF}}, image.Point{}, draw.Src)

	drawRect(img, image.Rect(88, 72, 424, 440), color.RGBA{0xFF, 0xFB, 0xF2, 0xFF})
	drawRect(img, image.Rect(108, 108, 404, 136), color.RGBA{0xD1, 0xB7, 0x7A, 0xFF})
	for i := 0; i < 4; i++ {
		y := 182 + i*48
		drawRect(img, image.Rect(128, y, 260, y+16), color.RGBA{0x31, 0x2A, 0x24, 0xFF})
		drawRect(img, image.Rect(284, y, 384, y+16), color.RGBA{0x7B, 0x2C, 0x1F, 0xFF})
	}
	drawChevron(img, 266, 220, 54, color.RGBA{0xB6, 0x4A, 0x32, 0xFF}, true)
	drawChevron(img, 266, 316, 54, color.RGBA{0xB6, 0x4A, 0x32, 0xFF}, false)
	return img
}

func makeSamplePage() image.Image {
	img := image.NewRGBA(image.Rect(0, 0, 1200, 1600))
	draw.Draw(img, img.Bounds(), &image.Uniform{color.RGBA{0xF2, 0xEC, 0xDE, 0xFF}}, image.Point{}, draw.Src)
	drawRect(img, image.Rect(70, 60, 1130, 1540), color.RGBA{0xFF, 0xFC, 0xF6, 0xFF})

	for y := 170; y < 1480; y += 110 {
		drawRect(img, image.Rect(120, y, 1080, y+3), color.RGBA{0xE2, 0xDA, 0xCA, 0xFF})
	}
	for x := 180; x < 1060; x += 220 {
		drawRect(img, image.Rect(x, 120, x+2, 1490), color.RGBA{0xF1, 0xEB, 0xDD, 0xFF})
	}

	drawHandLine(img, 160, 230, 980, 32, 8, color.RGBA{0x2E, 0x26, 0x21, 0xFF})
	drawHandLine(img, 160, 330, 920, 26, 7, color.RGBA{0x2E, 0x26, 0x21, 0xFF})
	drawHandLine(img, 160, 440, 860, 24, 6, color.RGBA{0x2E, 0x26, 0x21, 0xFF})
	drawHandLine(img, 160, 620, 780, 26, 7, color.RGBA{0x3A, 0x30, 0x28, 0xFF})
	drawHandLine(img, 160, 730, 840, 24, 6, color.RGBA{0x3A, 0x30, 0x28, 0xFF})
	drawHandLine(img, 160, 840, 760, 22, 6, color.RGBA{0x3A, 0x30, 0x28, 0xFF})
	drawHandLine(img, 160, 1040, 900, 24, 8, color.RGBA{0x2E, 0x26, 0x21, 0xFF})
	drawHandLine(img, 160, 1150, 760, 20, 7, color.RGBA{0x2E, 0x26, 0x21, 0xFF})

	drawRect(img, image.Rect(150, 1280, 420, 1360), color.RGBA{0xD9, 0xCC, 0xB4, 0xFF})
	drawRect(img, image.Rect(170, 1300, 400, 1340), color.RGBA{0x8C, 0x4B, 0x34, 0xFF})
	return img
}

func drawRect(img *image.RGBA, rect image.Rectangle, c color.Color) {
	draw.Draw(img, rect, &image.Uniform{c}, image.Point{}, draw.Src)
}

func drawChevron(img *image.RGBA, cx, cy, size int, c color.Color, right bool) {
	for step := -6; step <= 6; step++ {
		var x1, x2 int
		if right {
			x1, x2 = cx-size/2, cx+size/2
		} else {
			x1, x2 = cx+size/2, cx-size/2
		}
		drawLine(img, x1, cy-size/2+step, cx, cy+step, c)
		drawLine(img, cx, cy+step, x2, cy+size/2+step, c)
	}
}

func drawHandLine(img *image.RGBA, x, y, width, height, wobble int, c color.Color) {
	for dx := 0; dx < width; dx++ {
		baseY := y + int(math.Round(math.Sin(float64(dx)/24.0)*float64(wobble)))
		for dy := 0; dy < height; dy++ {
			jitter := int(math.Round(math.Sin(float64(dx+dy*9)/13.0) * 2))
			setSafe(img, x+dx, baseY+dy+jitter, c)
		}
	}
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, c color.Color) {
	dx := abs(x1 - x0)
	dy := -abs(y1 - y0)
	sx := -1
	if x0 < x1 {
		sx = 1
	}
	sy := -1
	if y0 < y1 {
		sy = 1
	}
	err := dx + dy
	for {
		setSafe(img, x0, y0, c)
		if x0 == x1 && y0 == y1 {
			return
		}
		e2 := 2 * err
		if e2 >= dy {
			err += dy
			x0 += sx
		}
		if e2 <= dx {
			err += dx
			y0 += sy
		}
	}
}

func setSafe(img *image.RGBA, x, y int, c color.Color) {
	if image.Pt(x, y).In(img.Bounds()) {
		img.Set(x, y, c)
	}
}

func abs(v int) int {
	if v < 0 {
		return -v
	}
	return v
}
